import './Navigation.css';
import { NavLink } from 'react-router-dom';

export default function Navigation() {
    return (
        <header>
            <nav className="wrap">
                <NavLink className="logo" to="/" end>AP<span>.</span></NavLink>
                <button className="menu-btn" type="button" aria-label="Ouvrir le menu">Menu</button>
                <div className="navlinks">
                <NavLink to="/profil">Profil</NavLink>
                <NavLink to="/experiences">Expériences</NavLink>
                <NavLink to="/competences">Compétences</NavLink>
                <NavLink to="/projets">Projets</NavLink>
                <NavLink to="/contact">Contact</NavLink>
                </div>
            </nav>
        </header>
    )
};
